/**
 * An Input preset for searching (`design/components/search-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentFill,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/search-input.module.css'
import Input from './Input'
import Kbd from '../structure/Kbd'

export interface SearchInputProps {
  'aria-describedby'?: string
  /**
   * Required unless a FormField supplies a label. Search boxes rarely have visible labels.
   */
  'aria-label'?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  /**
   * The clear button's accessible name, passed to Input. Defaults to `Clear`.
   */
  clearLabel?: string
  defaultValue?: string
  disabled?: boolean
  id?: string
  name?: string
  onChange?: (value: string) => void
  placeholder?: string
  /**
   * A hint such as `⌘K`. Display only. Menu's `kbd` rule applies here too, and the vocabulary
   * never binds a global shortcut.
   */
  shortcut?: string
  size?: 'sm' | 'md' | 'lg'
  value?: string
}

/** An Input preset for searching. */
export default function SearchInput(given: SearchInputProps): JSX.Element {
  const props = mergeProps(
    { placeholder: 'Search…', size: 'md', disabled: false } as Defaults<
      SearchInputProps,
      'placeholder' | 'size' | 'disabled'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const frame = elementRef<HTMLElement>()
    const focused = createCell(false)
    const mirror = createCell(props.defaultValue ?? '')
    const current = createDerived(() => props.value ?? mirror.value)
    const showShortcut = createDerived(
      () =>
        props.shortcut !== undefined && current.value === '' && !focused.value && !props.disabled,
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'SearchInput',
        element: () => frame.value?.querySelector('input'),
        state: () => ({ value: current.value, disabled: props.disabled }),
        actions: {
          fill: {
            argument: 'text',
            run: (value) => agentFill(frame.value?.querySelector('input'), value),
          },
          clear: () => agentFill(frame.value?.querySelector('input'), ''),
        },
        withholds: () => frame.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <span
        class={styles.search}
        data-shortcut={showShortcut.value ? '' : undefined}
        data-member="search-input"
        onfocusin={() => (focused.value = true)}
        onfocusout={() => (focused.value = false)}
        ref={frame.attach}
      >
        <Input
          type="search"
          icon="search"
          clearable={true}
          clearLabel={props.clearLabel}
          size={props.size}
          disabled={props.disabled}
          value={props.value}
          defaultValue={props.defaultValue}
          placeholder={props.placeholder}
          aria-label={props['aria-label']}
          aria-labelledby={props['aria-labelledby']}
          aria-describedby={props['aria-describedby']}
          id={props.id}
          name={props.name}
          onChange={($event) => ((mirror.value = $event), props.onChange?.($event))}
          trailing={
            showShortcut.value ? (
              <span class={styles.hint} aria-hidden="true">
                <Kbd>{props.shortcut}</Kbd>
              </span>
            ) : undefined
          }
        />
      </span>
    )
  })
}
